actions.script:
const financeTypes = {MantleInvoice:'invoices',MantlePayment:'payments',MantleGlAccount:'accounts',MantleAcctgTrans:'journals',
    'mantle.account.invoice.Invoice':'invoices','mantle.account.payment.Payment':'payments','mantle.ledger.account.GlAccount':'accounts','mantle.ledger.transaction.AcctgTrans':'journals'}
// an employment (People's HR host, impl-people P2): its Employee360 under People for an HR reader of the employer,
// else nowhere
if (recordEntityName === 'mantle.humanres.employment.Employment') {
    url = ec.resource.script('component://mr-boss/service/ironstone/people/People.js').employmentLink(id)
    icon = 'sym_o_badge'
    return
}
// a lead or opportunity (IronStone Sales P4, F39): its OpportunityDetail under Sales for a Sales reader of it, else nowhere
if (recordEntityName === 'mantle.sales.opportunity.SalesOpportunity') {
    url = ec.resource.script('component://mr-boss/service/ironstone/sales/Sales.js').recordLink('opportunity', id)
    icon = 'sym_o_trending_up'
    return
}
// a shared device (Admin P18; the clocking kiosk's refusals notice, impl-people follow-up 4): Admin's Security › Devices
// with the device, where it is revoked, for one who may read it there and whose groups open that screen, else nowhere
if (recordEntityName === 'moqui.security.DeviceCredential') {
    url = ec.resource.script('component://mr-boss/service/ironstone/admin/Admin.js').recordLink('device', id)
    icon = 'sym_o_tv_signin'
    return
}
// a qualification (People's qualification host, impl-people P18): the person's or HR's qualifications with its files, else
// nowhere
if (recordEntityName === 'mantle.humanres.ability.PartyQualification') {
    url = ec.resource.script('component://mr-boss/service/ironstone/people/People.js').qualificationLink(id)
    icon = 'sym_o_workspace_premium'
    return
}
// a review (People's review host, impl-people P20): its ReviewDetail under People for one who reads it, else nowhere
if (recordEntityName === 'mantle.humanres.ability.PerformanceReview') {
    url = ec.resource.script('component://mr-boss/service/ironstone/people/People.js').reviewLink(id)
    icon = 'sym_o_rate_review'
    return
}
// a confidential case (People's grievances, impl-people P21): its RequestDetail under People for its people, else nowhere
if ((recordEntityName === 'mantle.request.Request' || docType === 'MantleRequest')
        && ec.resource.script('component://mr-mantle/service/mantle/request/PeopleCases.js').isCase(id)) {
    url = ec.resource.script('component://mr-boss/service/ironstone/people/People.js').caseLink(id)
    icon = 'sym_o_shield_person'
    return
}
const financeKind = financeTypes[docType] || financeTypes[recordEntityName]
if (financeKind && ec.user.userId) {
    // Accounting's own permission check (the Mantle finance permissions), not group names
    url = ec.resource.script('component://mr-boss/service/ironstone/accounting/Accounting.js').recordLink(financeKind, id)
    icon = 'sym_o_account_balance'
    return
}
// sales orders open under Customer Service for a user who may work with them there (ironstone.customerservice's
// scope: the root grant, the selling organization and the customer, impl-customer-service P1; Home's lookup until P3
// builds OrderDetail), else nowhere, as before (no other app has a sales order screen, impl-purchasing F46); a
// customer once Customer Service has its Customer360 (P3; until then its Commons contact below); cases, returns and
// warranty claims as their phases build them, leaving Projects' and Commons' requests as they are (F9)
// a support case (impl-customer-service P2) opens CaseDetail for a Customer Service user who sees it; anyone else
// keeps its Projects or Commons link below
if (ec.user.userId && (recordEntityName === 'mantle.request.Request' || docType === 'MantleRequest')
        && ec.entity.find('mantle.request.support.CaseProfile').condition('requestId', id).disableAuthz().count() > 0) {
    const caseUrl = ec.resource.script('component://mr-boss/service/ironstone/customerservice/CustomerService.js').recordLink('case', id)
    if (caseUrl) {
        url = caseUrl
        icon = 'sym_o_support_agent'
        return
    }
}
if (ec.user.userId && (recordEntityName === 'mantle.order.OrderHeader' || recordEntityName === 'mantle.party.Party'
        || docType === 'MantleParty')) {
    const customerService = ec.resource.script('component://mr-boss/service/ironstone/customerservice/CustomerService.js')
    // a sales order Customer Service does not take (its link is null: a user out of its scope) falls through to
    // the branches below, so Commerce's store orders and carts open there (impl-commerce F42)
    if (recordEntityName === 'mantle.order.OrderHeader' && customerService.isSalesOrder(id)) {
        const serviceUrl = customerService.recordLink('order', id)
        if (serviceUrl) {
            url = serviceUrl
            icon = 'sym_o_receipt_long'
            return
        }
    }
    if (recordEntityName !== 'mantle.order.OrderHeader' && customerService.hasScreen('customer')) {
        const customerUrl = customerService.recordLink('customer', id)
        if (customerUrl) {
            url = customerUrl
            icon = 'sym_o_person'
            return
        }
    }
}
// stores open under Commerce for a user who may work with them there (ironstone.commerce's scope: the root grant,
// the store's organization and a store-limited staff member's stores, impl-commerce P1; Home scoped to the store
// until P2 builds StoreDetail), else nowhere; a store's orders and carts in P8 (F8, F42)
if (ec.user.userId && recordEntityName === 'mantle.product.store.ProductStore') {
    url = ec.resource.script('component://mr-boss/service/ironstone/commerce/Commerce.js').recordLink('store', id)
    icon = 'sym_o_storefront'
    return
}
// P8: a store's order opens OrderDetail, an open one CartDetail, under Commerce for a user who works its store
// (F8); anyone else goes on to the branches below
if (ec.user.userId && recordEntityName === 'mantle.order.OrderHeader') {
    const storeOrder = ec.entity.find('mantle.order.OrderHeader').condition('orderId', id).disableAuthz().one()
    if (storeOrder?.productStoreId) {
        const kind = storeOrder.statusId === 'OrderOpen' ? 'cart' : 'order'
        const commerceUrl = ec.resource.script('component://mr-boss/service/ironstone/commerce/Commerce.js').recordLink(kind, id)
        if (commerceUrl) {
            url = commerceUrl
            icon = kind === 'cart' ? 'sym_o_shopping_cart' : 'sym_o_receipt_long'
            return
        }
    }
}
// purchase orders, supplier quotes and purchase agreements open under Purchasing for a user who may work with them
// there (ironstone.purchasing's scope: the root grant, the buying organization and the supplier,
// impl-purchasing P1), else nowhere; a purchase request, RFQ or supplier return once its Purchasing screen is
// built (until then its other apps' links below)
const purchasingEntities = {'mantle.order.OrderHeader':'order', 'mantle.party.agreement.Agreement':'agreement',
    'mantle.request.Request':'request', 'mantle.order.return.ReturnHeader':'supplierReturn'}
if (ec.user.userId && Object.prototype.hasOwnProperty.call(purchasingEntities, recordEntityName)) {
    const purchasing = ec.resource.script('component://mr-boss/service/ironstone/purchasing/Purchasing.js')
    let kind = purchasingEntities[recordEntityName]
    if (kind === 'order') kind = purchasing.orderKind(id)
    if (kind === 'request') kind = purchasing.requestKind(id)
    const ownLink = kind === 'order' || kind === 'quote' || kind === 'agreement'
    if (kind && (ownLink || purchasing.hasScreen(kind))) {
        url = purchasing.recordLink(kind, id)
        icon = {order:'sym_o_receipt_long', quote:'sym_o_request_quote', agreement:'sym_o_handshake', request:'sym_o_add_task',
            rfq:'sym_o_contract', supplierReturn:'sym_o_assignment_return'}[kind]
        // an RFQ opens only QuoteRequestDetail, never another app's RequestDetail (impl-purchasing P11, R-PUR-13)
        if (url || ownLink || kind === 'rfq') return
    }
}
// shipments, stock, lots, containers, counts, returns and facilities open under Warehouse for a user who may work
// with them there (ironstone.warehouse's scope: the root grant, the facility and the organizations), else nowhere
const warehouseTypes = {MantleShipment:'shipment', MantleAsset:'asset', MantleFacility:'facility',
    'mantle.shipment.Shipment':'shipment', 'mantle.product.asset.Asset':'asset', 'mantle.product.asset.Lot':'lot',
    'mantle.product.asset.Container':'container', 'mantle.product.asset.PhysicalInventory':'count',
    'mantle.order.return.ReturnHeader':'return', 'mantle.facility.Facility':'facility',
    'mantle.product.quality.QualityInspection':'inspection'}
const warehouseKind = warehouseTypes[docType] || warehouseTypes[recordEntityName]
if (warehouseKind && ec.user.userId) {
    url = ec.resource.script('component://mr-boss/service/ironstone/warehouse/Warehouse.js').recordLink(warehouseKind, id)
    icon = {shipment:'sym_o_local_shipping', asset:'sym_o_package_2', lot:'sym_o_barcode', container:'sym_o_pallet',
        count:'sym_o_fact_check', return:'sym_o_assignment_return', facility:'sym_o_warehouse',
        inspection:'sym_o_verified'}[warehouseKind]
    return
}
// a maintenance work order and its steps (the root has a MaintenanceWorkOrder row) open their work order under
// Maintenance for a user Maintenance admits to it, else nowhere: they are no task (impl-maintenance P3)
if (recordEntityName === 'mantle.work.effort.WorkEffort' && ec.entity.isEntityDefined('mantle.work.maintenance.MaintenanceWorkOrder')) {
    const effort = ec.entity.find(recordEntityName).condition('workEffortId', id).disableAuthz().one()
    const rootId = effort ? (effort.rootWorkEffortId || effort.workEffortId) : null
    if (rootId && ec.entity.find('mantle.work.maintenance.MaintenanceWorkOrder').condition('workEffortId', rootId).disableAuthz().count() > 0) {
        url = ec.resource.script('component://mr-boss/service/ironstone/maintenance/Maintenance.js').execute('recordLink',
            {recordType: 'workOrder', recordId: rootId}).url
        icon = 'sym_o_handyman'
        return
    }
}
// runs, their operations, methods, routings and work centers open under Manufacturing for a user who may work with
// them there (ironstone.manufacturing's scope: the root grant and the organizations, impl-manufacturing P1), else as
// below (a method or routing in Products' method screens)
const manufacturingEntities = {'mantle.product.bom.ProductBom':'method', 'mantle.work.production.WorkCenter':'workCenter',
    'mantle.work.effort.WorkEffort':null}
if (ec.user.userId && Object.prototype.hasOwnProperty.call(manufacturingEntities, recordEntityName)) {
    let kind = manufacturingEntities[recordEntityName]
    if (!kind) {
        const effort = ec.entity.find(recordEntityName).condition('workEffortId', id).disableAuthz().one()
        const runId = effort && effort.purposeEnumId !== 'WepProductionRun' ? (effort.rootWorkEffortId || effort.parentWorkEffortId) : null
        const above = runId ? ec.entity.find(recordEntityName).condition('workEffortId', runId).selectField('purposeEnumId').disableAuthz().one() : null
        kind = effort?.purposeEnumId === 'WepProductionRun' ? 'run' : ['WepRouting','WepRoutingTask'].includes(effort?.purposeEnumId) ? 'routing'
            : above?.purposeEnumId === 'WepProductionRun' ? 'operation' : null
    }
    const manufacturing = ec.resource.script('component://mr-boss/service/ironstone/manufacturing/Manufacturing.js')
    // a method or routing opens under Manufacturing once its screen there is built (P2), until then in Products
    const manufacturingUrl = kind && (!['method', 'routing'].includes(kind) || manufacturing.hasScreen(kind))
        ? manufacturing.recordLink(kind, id) : null
    // a run or its operation is no task or event (impl-manufacturing F38, F39): without Manufacturing it opens the
    // run's material screen under Warehouse for a Warehouse user who may work with it, else nowhere
    const runLink = !manufacturingUrl && kind === 'run'
        ? ec.resource.script('component://mr-boss/service/ironstone/warehouse/Warehouse.js').recordLink('run', id) : null
    if (manufacturingUrl || runLink || kind === 'run' || kind === 'operation') {
        url = manufacturingUrl || runLink
        icon = {run:'sym_o_precision_manufacturing', operation:'sym_o_task_alt', method:'sym_o_account_tree', routing:'sym_o_route',
            workCenter:'sym_o_factory'}[kind]
        return
    }
}
if (recordEntityName === 'mantle.product.cost.ProductStandardCost') {
    const access=ec.service.sync().name('mantle.product.CostServices.get#StandardCostAccess').parameters({productStandardCostId:id}).disableAuthz().call() || {}
    url=access.recordVisible?'/qapps/Products/Prices/StandardCosts?productId='+encodeURIComponent(access.record.productId)+'&productStandardCostId='+encodeURIComponent(id):null
    icon='sym_o_request_quote'
    return
}
if (recordEntityName === 'mantle.product.bom.ProductBom') {
    const access = ec.service.sync().name('mantle.product.BomServices.get#BomAccess').parameters({productBomId:id}).disableAuthz().call() || {}
    const product = access.recordVisible ? ec.service.sync().name('ironstone.products.CatalogServices.get#CatalogRecord')
        .parameters({recordId:access.record.productId,checkOnly:true}).disableAuthz().call()?.record : null
    url = product ? '/qapps/Products/Products/Product360/BOM?productId='+encodeURIComponent(product.productId)+'&productBomId='+encodeURIComponent(id) : null
    icon = 'sym_o_account_tree'
    return
}
if (recordEntityName === 'mantle.work.effort.WorkEffort') {
    const row = ec.entity.find(recordEntityName).condition('workEffortId',id).disableAuthz().one()
    if (row && ['WepRouting','WepRoutingTask'].includes(row.purposeEnumId)) {
        const routeId = row.purposeEnumId==='WepRouting' ? id : row.parentWorkEffortId
        const access = ec.service.sync().name('mantle.work.RoutingServices.get#RoutingAccess').parameters({workEffortId:id}).disableAuthz().call() || {}
        url = null; icon = 'sym_o_route'
        if (access.recordVisible) for (const bom of ec.entity.find('mantle.product.bom.ProductBom').condition('routingWorkEffortId',routeId).disableAuthz().list()) {
            const product = ec.service.sync().name('ironstone.products.CatalogServices.get#CatalogRecord').parameters({recordId:bom.productId,checkOnly:true}).disableAuthz().call()?.record
            if (product) { url='/qapps/Products/Products/Product360/BOM/RoutingDetail?productId='+encodeURIComponent(product.productId)+'&productBomId='+encodeURIComponent(bom.productBomId); break }
        }
        return
    }
}
const catalogTypes = {'MantleProduct':'mantle.product.Product','MantleProductCategory':'mantle.product.category.ProductCategory',
    'MantleProductFeature':'mantle.product.feature.ProductFeature','MantleProductFeatureGroup':'mantle.product.feature.ProductFeatureGroup'}
const catalogRoutes = {'mantle.product.Product':'Products/Product360?productId=',
    'mantle.product.category.ProductCategory':'Categories/CategoryDetail?productCategoryId=',
    'mantle.product.feature.ProductFeature':'Features/FeatureDetail?productFeatureId=',
    'mantle.product.feature.ProductFeatureGroup':'Features/FeatureGroups/FeatureGroupDetail?productFeatureGroupId='}
const own = (object,key) => Object.prototype.hasOwnProperty.call(object,key)
const catalogEntity = own(catalogTypes,docType) ? catalogTypes[docType] : own(catalogRoutes,recordEntityName) ? recordEntityName : null
if (catalogEntity) {
    // a catalog read (PRODUCT_CATALOG_VIEW, which Warehouse users hold too) links into Products only for a user
    // who may open Products
    const mayOpenProducts = ec.resource.script('component://mr-boss/service/ironstone/products/SharedContext.js').mayOpen('Products')
    const found = !mayOpenProducts ? {} : ec.service.sync().name('ironstone.products.CatalogServices.get#CatalogRecord')
        .parameters({recordEntityName:catalogEntity,recordId:id,checkOnly:true}).disableAuthz().call() || {}
    url = found.record ? '/qapps/Products/'+catalogRoutes[catalogEntity]+encodeURIComponent(String(id)) : null
    // a Warehouse user who may not open Products opens a product in Warehouse's Product360 (impl-warehouse P4, B2)
    if (!url && !mayOpenProducts && catalogEntity === 'mantle.product.Product')
        url = ec.resource.script('component://mr-boss/service/ironstone/warehouse/Warehouse.js').recordLink('product', id)
    // a Purchasing user who may not open Products or Warehouse opens it in Purchasing's Product360 (impl-purchasing P2)
    if (!url && !mayOpenProducts && catalogEntity === 'mantle.product.Product')
        url = ec.resource.script('component://mr-boss/service/ironstone/purchasing/Purchasing.js').recordLink('product', id)
    icon = catalogEntity==='mantle.product.Product' ? 'sym_o_inventory_2' : catalogEntity==='mantle.product.category.ProductCategory' ? 'sym_o_category' : 'sym_o_style'
    return
}
const q = encodeURIComponent(String(id))
let type = docType
if (!type && recordEntityName) {
    type = {'mantle.party.Party': 'MantleParty', 'mantle.request.Request': 'MantleRequest', 'mantle.work.effort.WorkEffort': 'MantleWorkEffort',
        'moqui.resource.wiki.WikiPage': 'MantleWikiPage', 'mantle.party.communication.CommunicationEvent': 'MantleCommunicationEvent'}[recordEntityName] || null
    if (type === 'MantleWorkEffort' && !workEffortTypeEnumId) workEffortTypeEnumId = ec.entity.find('mantle.work.effort.WorkEffort')
            .condition('workEffortId', id).selectField('workEffortTypeEnumId').one()?.workEffortTypeEnumId || null
    if (type === 'MantleParty' && !partyTypeEnumId) partyTypeEnumId = ec.entity.find('mantle.party.Party')
            .condition('partyId', id).selectField('partyTypeEnumId').one()?.partyTypeEnumId || null
}
if (type === 'MantleWorkEffort') type = workEffortTypeEnumId === 'WetEvent' ? 'MantleEvent' : workEffortTypeEnumId === 'WetTask' ? 'MantleTask'
    : workEffortTypeEnumId === 'WetProject' ? 'MantleProject' : workEffortTypeEnumId === 'WetSprint' ? 'MantleSprint'
    : workEffortTypeEnumId === 'WetMilestone' ? 'MantleMilestone' : workEffortTypeEnumId === 'WetRelease' ? 'MantleRelease' : null
// a confidential issue's task the user is no Owner of has no link, from a search result, a notification or a card
// (projects/HiddenItems.js)
if (type === 'MantleTask' && !ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').shown(id)) { url = null; icon = 'sym_o_task_alt'; return }
// a client contact (the PROJECT_CLIENT permission, impl-projects.md P10) has Projects alone: a project, work item, milestone,
// release or request opens its detail there (which checks the client may see it), anything else has no link
if (ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) {
    const client = {MantleProject: ['/qapps/Projects/Projects/ProjectDetail?workEffortId=', 'sym_o_assignment'],
        MantleTask: ['/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=', 'sym_o_task_alt'],
        MantleMilestone: ['/qapps/Projects/Projects/MilestoneDetail?workEffortId=', 'sym_o_flag'],
        MantleRelease: ['/qapps/Projects/Projects/ReleaseDetail?workEffortId=', 'sym_o_new_releases'],
        MantleRequest: ['/qapps/Projects/Requests/RequestDetail?requestId=', 'sym_o_support']}[type]
    // a task of no project is no work item
    const loose = type === 'MantleTask' && !ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id)
            .selectField('rootWorkEffortId').disableAuthz().one()?.rootWorkEffortId
    url = client && !loose ? client[0] + q : null
    icon = client ? client[1] : 'sym_o_description'
    return
}
// a wiki page review (topics WikiPageReview, WikiPageReviewDecision) opens its page on the review's compare
if (!type && recordEntityName === 'moqui.resource.wiki.WikiPageReview') {
    const review = ec.entity.find('moqui.resource.wiki.WikiPageReview').condition('wikiPageReviewId', id).one()
    url = review ? '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(review.wikiPageId) + '&review=' + q : null
    icon = 'sym_o_rate_review'
    return
}
// whether the user may open IronStone Projects: an authorization of the user's groups on its root, with no deny (People
// P10: or on another screen, People's time area)
const mayOpenProjects = (root = 'component://mr-boss/screen/Projects.xml') => {
    if (!ec.user.userId) return false
    try {
        const groupIds = Array.from(ec.user.getUserGroupIdSet() || [])
        const rows = Array.from(ec.entity.find('moqui.security.ArtifactAuthzCheckView').condition('userGroupId', 'in', groupIds)
                .condition('artifactTypeEnumId', 'AT_XML_SCREEN').condition('authzActionEnumId', 'in', ['AUTHZA_ALL', 'AUTHZA_VIEW'])
                .disableAuthz().list()).filter((row) => row.nameIsPattern === 'Y' ? new RegExp(`^(?:${row.artifactName})$`).test(root)
                        : row.artifactName === root)
        return rows.some((row) => row.authzTypeEnumId === 'AUTHZT_ALLOW' || row.authzTypeEnumId === 'AUTHZT_ALWAYS')
                && !rows.some((row) => row.authzTypeEnumId === 'AUTHZT_DENY')
    } catch (err) {
        ec.logger.error(`Record link of ${type || recordEntityName} ${id}: the Projects authorization of user ${ec.user.userId} was not read: ${err}`)
        return false
    }
}
// a timesheet (the timesheet topics, Chatter on it) opens its TimesheetDetail in Projects (impl-projects.md P6a), else under
// People's time area for a People user or a self-service employee (impl-people P10: the same screen mounted there)
if (!type && recordEntityName === 'mantle.work.time.Timesheet') {
    url = mayOpenProjects() ? '/qapps/Projects/Time/TimesheetDetail?timesheetId=' + q
            : mayOpenProjects('component://mr-boss/screen/People.xml') || mayOpenProjects('component://mr-boss/screen/People/Time.xml')
            ? '/qapps/People/Time/TimesheetDetail?timesheetId=' + q : null
    icon = 'sym_o_schedule'
    return
}
// the user's own week (docType MantleTimesheetWeek, id a day of the week; the timesheet topics of the person, impl-people P10:
// a week with no timesheet yet too) opens in My time, Projects' for a Projects user, else People's
if (type === 'MantleTimesheetWeek') {
    const week = '/Time/MyTime?weekDate=' + q
    url = mayOpenProjects() ? '/qapps/Projects' + week
            : mayOpenProjects('component://mr-boss/screen/People.xml') || mayOpenProjects('component://mr-boss/screen/People/Time.xml')
            ? '/qapps/People' + week : null
    icon = 'sym_o_schedule'
    return
}
// a merge request or a repository (the code topics, Chatter on them) opens in Projects' Code
if (!type && (recordEntityName === 'moqui.resource.GitMergeRequest' || recordEntityName === 'moqui.resource.GitRepository')) {
    const isMergeRequest = recordEntityName === 'moqui.resource.GitMergeRequest'
    url = mayOpenProjects() ? (isMergeRequest ? '/qapps/Projects/Code/MergeRequestDetail?mergeRequestId=' : '/qapps/Projects/Code/RepositoryDetail?repositoryId=') + q : null
    icon = isMergeRequest ? 'sym_o_merge' : 'sym_o_folder_data'
    return
}
// a sprint (its Chatter, the retrospective) opens its SprintDetail in Projects
if (type === 'MantleSprint') {
    url = mayOpenProjects() ? '/qapps/Projects/WorkItems/SprintDetail?workEffortId=' + q : null
    icon = 'sym_o_sprint'
    return
}
// a milestone or a release (its Chatter, the topic ReleasePublished) opens its detail in Projects
if (type === 'MantleMilestone' || type === 'MantleRelease') {
    const release = type === 'MantleRelease'
    url = mayOpenProjects() ? (release ? '/qapps/Projects/Projects/ReleaseDetail?workEffortId=' : '/qapps/Projects/Projects/MilestoneDetail?workEffortId=') + q : null
    icon = release ? 'sym_o_new_releases' : 'sym_o_flag'
    return
}
// IronStone Projects: a project, and a task or a request of a project, for a user who may open the app
if (type === 'MantleProject' || type === 'MantleTask' || type === 'MantleRequest') {
    const entityName = type === 'MantleRequest' ? 'mantle.request.Request' : 'mantle.work.effort.WorkEffort'
    const inProject = type === 'MantleProject' || !!ec.entity.find(entityName).condition(type === 'MantleRequest' ? 'requestId' : 'workEffortId', id)
            .selectField('rootWorkEffortId').disableAuthz().one()?.rootWorkEffortId
    if (inProject && ec.user.userId) {
        if (mayOpenProjects()) {
            const projects = {MantleProject: ['/qapps/Projects/Projects/ProjectDetail?workEffortId=', 'sym_o_assignment'],
                MantleTask: ['/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=', 'sym_o_task_alt'],
                MantleRequest: ['/qapps/Projects/Requests/RequestDetail?requestId=', 'sym_o_support']}[type]
            url = projects[0] + q
            icon = projects[1]
            return
        }
    }
}
const links = {
    MantleParty: ['/qapps/Commons/Contacts/ContactDetail?partyId=' + q, partyTypeEnumId === 'PtyOrganization' ? 'sym_o_corporate_fare' : 'sym_o_person'],
    MantleTask: ['/qapps/Commons/Tasks/TaskDetail?workEffortId=' + q, 'sym_o_task_alt'],
    MantleEvent: ['/qapps/Commons/Calendar/EventDetail?workEffortId=' + q, 'sym_o_event'],
    MantleRequest: ['/qapps/Commons/Requests/RequestDetail?requestId=' + q, 'sym_o_support'],
    // a page of the user's own notes opens in Notes
    MantleWikiPage: [(String(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', id).selectField('wikiSpaceId').one()?.wikiSpaceId || '')
        === 'NOTES_' + ec.user.userId ? '/qapps/Commons/Notes?wikiPageId=' : '/qapps/Commons/Knowledge?wikiPageId=') + q, 'sym_o_description'],
    MantleCommunicationEvent: ['/qapps/Comms/Inbox/MessageDetail?communicationEventId=' + q, 'sym_o_mail'],
    // no project screen in Commons: a user without Projects has no link to a project
    MantleProject: [null, 'sym_o_assignment']
}
const found = links[type] || [null, 'sym_o_description']
url = found[0]
icon = found[1]

const asLink = (url) => url ? String(url).replace(/^\/apps\//, '/qapps/') : null
const hiddenItems = ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js')
for (const result of (found.results || [])) {
    const key = result.key || {}
    const id = key[Object.keys(key)[0]] || result.id
    const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({docType: result.entityType, id: id,
        partyTypeEnumId: result.attributes ? result.attributes.partyTypeEnumId : null}).call()
    // a Warehouse kind (shipment, asset, facility) opens under Warehouse or not at all, never the search's own screen
    const warehouseDoc = ['MantleShipment', 'MantleAsset', 'MantleFacility'].includes(result.entityType)
    // a task is a row only with its own link and for a user who may see it (HiddenItems.js mayName): never the
    // search's own link and title for one that is not the user's to see
    const taskDoc = result.entityType === 'MantleTask'
    if (taskDoc && (!link.url || !hiddenItems.mayName(id))) continue
    const url = link.url || (warehouseDoc ? null : asLink(result.url))
    if (!url) continue
    const subtitle = [result.entityTypeName, result.code, result.subtitle].filter((part) => part).join(' · ')
    rows.push({title: result.title, subtitle: subtitle, icon: link.icon, url: url})
}
moreUrl = '/qapps/Commons/Search?q=' + encodeURIComponent(text)

iterate.script:
const title = ec.resource.expand('PartyNameOnlyTemplate', '', party) || party.partyId
const kind = party.partyTypeEnumId === 'PtyOrganization' ? ec.l10n.localize('Organization') : ec.l10n.localize('Person')
rows.push({title: title.trim() || party.partyId, subtitle: [kind, party.pseudoId || party.partyId].join(' · '), icon: link.icon, url: link.url})

actions.script:
rows = []
const out = ec.service.sync().name('org.moqui.resource.WikiServices.search#WikiPages').parameters({text: text, limit: Math.max(20, (limit || 5) * 4)}).call() || {}
const mine = ec.user.userId ? 'NOTES_' + ec.user.userId : null
for (const page of Array.from(out.pageList || [])) {
    if (rows.length >= (limit || 5)) break
    const isNotes = String(page.wikiSpaceId).startsWith('NOTES_')
    if (isNotes && page.wikiSpaceId !== mine) continue
    const path = String(page.pagePath || '')
    rows.push({title: page.title || page.pageName || path, subtitle: (isNotes ? ec.l10n.localize('My notes') : (page.spaceDescription || page.wikiSpaceId))
            + (path ? ' · ' + path : ''), icon: isNotes ? 'sym_o_sticky_note_2' : 'sym_o_description',
        url: (isNotes ? '/qapps/Commons/Notes?wikiPageId=' : '/qapps/Commons/Knowledge?wikiPageId=') + encodeURIComponent(page.wikiPageId)})
}

const seen = new Set()
for (const event of eventList) {
    if (seen.has(event.workEffortId) || rows.length >= (limit || 5)) continue
    seen.add(event.workEffortId)
    const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({docType: 'MantleEvent', id: event.workEffortId}).call()
    rows.push({title: event.workEffortName, subtitle: ec.l10n.format(event.estimatedStartDate, 'EEE d MMM yyyy HH:mm'), icon: link.icon, url: link.url})
}

const link = (parameters) => ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters(parameters).call()
const add = (title, kind, id, found) => { if (found.url) rows.push({title: title || id, subtitle: kind + ' · ' + id, icon: found.icon, url: found.url}) }
if (found.party) {
    const party = found.party
    add(ec.resource.expand('PartyNameOnlyTemplate', '', party).trim(), ec.l10n.localize(party.partyTypeEnumId === 'PtyOrganization' ? 'Organization' : 'Person'),
        party.pseudoId || party.partyId, link({docType: 'MantleParty', id: party.partyId, partyTypeEnumId: party.partyTypeEnumId}))
}
if (found.workEffort) {
    const workEffort = found.workEffort
    const kind = workEffort.workEffortTypeEnumId === 'WetEvent' ? 'Event' : workEffort.workEffortTypeEnumId === 'WetTask' ? 'Task' : 'Work'
    add(workEffort.workEffortName, ec.l10n.localize(kind), workEffort.workEffortId,
        link({docType: 'MantleWorkEffort', id: workEffort.workEffortId, workEffortTypeEnumId: workEffort.workEffortTypeEnumId}))
}
if (found.request) add(found.request.requestName, ec.l10n.localize('Request'), found.request.requestId,
    link({docType: 'MantleRequest', id: found.request.requestId}))
if (found.communicationEvent) add(found.communicationEvent.subject, ec.l10n.localize('Message'), found.communicationEvent.communicationEventId,
    link({docType: 'MantleCommunicationEvent', id: found.communicationEvent.communicationEventId}))
